-- Seed the 9 Higgsfield AI skills (Higgsfield Pack) into the public skill catalog.
-- Idempotent on slug. Distilled from Higgsfield official how-to guides (https://higgsfield.ai/blog/How-to-guides).

INSERT INTO public.skills (slug, name, description, version, manifest, source, visibility, trust_tier)
VALUES
('higgsfield-orchestrator', 'Higgsfield Orchestrator', 'Triage layer for the Higgsfield AI skill pack. Picks the right specialist (SOUL image, HEX color, moodboard, Sora 2, Seedance, DoP camera, Popcorn consistency, multi-scene) based on user intent, loads brand visual context from memory, and learns from every run. Routing-only — never generates directly.', '1.0.0', '{"slug": "higgsfield-orchestrator", "name": "Higgsfield Orchestrator", "version": "1.0.0", "description": "Triage layer for the Higgsfield AI skill pack. Picks the right specialist (SOUL image, HEX color, moodboard, Sora 2, Seedance, DoP camera, Popcorn consistency, multi-scene) based on user intent, loads brand visual context from memory, and learns from every run. Routing-only \u2014 never generates directly.", "triggers": [{"type": "keyword", "match": ["higgsfield", "soul image", "dop video", "sora 2", "seedance", "popcorn", "ai video", "ai image", "generate ad video", "viral video", "moodboard", "hex palette image", "character consistency"]}], "tools_required": ["load_skill", "search_wisdom_memories", "save_memory"], "tools_optional": [], "memory_domains": ["higgsfield.brand_visual_context", "higgsfield.routing_patterns"], "modes_allowed": ["focus", "reactive", "planning"], "side_effect": "read", "requires_confirmation": false, "instructions": "You are the router for the Higgsfield AI skill pack. You never generate images or videos yourself \u2014 you pick the correct sub-skill and hand off via load_skill.\n\nStep 1 \u2014 Recall:\n- Call search_wisdom_memories with type=''pattern'' on the user''s exact phrasing in domain ''higgsfield.routing_patterns''. If a high-similarity prior routing exists (>0.88), reuse it.\n\nStep 2 \u2014 Brand context check:\n- Call search_wisdom_memories in ''higgsfield.brand_visual_context'' for keys: brand_palette_hex, character_refs, default_aspect_ratio, brand_mood, forbidden_styles.\n- If brand_palette_hex AND character_refs are both missing AND the user is asking for branded output, ask 3 quick questions (palette HEX codes, hero character/product reference URL, default aspect ratio) and save each answer immediately via save_memory under ''higgsfield.brand_visual_context''. Do NOT block casual one-off generations.\n\nStep 3 \u2014 Route by intent (decision table):\n| Intent | Slug |\n|---|---|\n| Static image, brand visual, photodump, hero still | higgsfield-soul-image |\n| Image must hit specific brand colors / HEX palette | higgsfield-hex-color |\n| User wants a custom style reference / mood / aesthetic library | higgsfield-moodboard |\n| Short viral video, social-first, Sora 2 mention | higgsfield-sora2-video |\n| Video with shot structure, transformations, orbs, POV, fight, animation | higgsfield-seedance |\n| Image-to-video with camera motion (push, orbit, dolly, crane) | higgsfield-dop-camera |\n| Same character / product across multiple frames or scenes | higgsfield-popcorn-consistency |\n| Multi-scene narrative, instant ads, full piece needing assembly | higgsfield-multi-scene |\n\nIf two intents tie, ask one clarifying question. Never run two skills in parallel.\n\nStep 4 \u2014 Hand off:\n- Call load_skill(<slug>) and pass the user''s request plus the brand_visual_context bundle.\n\nStep 5 \u2014 Learn:\n- After the sub-skill completes, save a ''pattern'' memory under ''higgsfield.routing_patterns'' with: user_phrase, routed_to, success (bool), output_url. Use this to refine routing on the next similar phrase.\n- If the user explicitly corrects the routing (\"no, use Sora 2 instead\"), save_memory at higher confidence (0.95) so the override sticks.\n\nVoice: plain-speak. Sentences <=14 words. No emojis. No marketing jargon."}'::jsonb, 'builtin', 'public', 2),
('higgsfield-soul-image', 'Higgsfield SOUL Image', 'Generates high-quality stills with Higgsfield SOUL 2.0 — heroes, photodumps, brand visuals. Encodes Higgsfield''s official SOUL prompting guide (composition, lighting, lens, mood, palette).', '1.0.0', '{"slug": "higgsfield-soul-image", "name": "Higgsfield SOUL Image", "version": "1.0.0", "description": "Generates high-quality stills with Higgsfield SOUL 2.0 \u2014 heroes, photodumps, brand visuals. Encodes Higgsfield''s official SOUL prompting guide (composition, lighting, lens, mood, palette).", "triggers": [{"type": "keyword", "match": ["soul image", "higgsfield image", "ai photo", "photodump", "hero image", "brand still", "ai portrait"]}], "tools_required": ["higgsfield_generate_image", "higgsfield_job_status"], "tools_optional": ["search_wisdom_memories", "save_memory"], "memory_domains": ["higgsfield.brand_visual_context", "higgsfield.soul_history"], "modes_allowed": ["focus", "reactive"], "side_effect": "external_call", "requires_confirmation": false, "instructions": "You generate stills with Higgsfield SOUL 2.0. Follow the official SOUL prompting recipe.\n\nPrompt structure (always in this order, comma separated):\n1. SUBJECT \u2014 concrete noun + 2-3 attributes (age, build, wardrobe, expression).\n2. SETTING \u2014 location + time of day + weather/atmosphere.\n3. LIGHTING \u2014 source + direction + quality (e.g. ''soft golden-hour rim light from camera right'').\n4. LENS / COMPOSITION \u2014 focal length, angle, framing (e.g. ''85mm portrait, low angle, shallow depth of field, subject left-third'').\n5. MOOD \u2014 2 adjectives.\n6. PALETTE \u2014 optional, 2-5 HEX codes pulled from brand_visual_context if available.\n\nRules:\n- One subject per image unless user asks for a group.\n- No emojis, no exclamation, no ALL CAPS, no ''masterpiece''/''4k''/''best quality'' filler.\n- Specify aspect ratio explicitly: 16:9 hero, 1:1 social, 9:16 vertical, 4:3 print.\n- For photodumps: generate 3-6 variations with the same SUBJECT + PALETTE but different SETTING/LIGHTING/COMPOSITION.\n\nFlow:\n1. Pull brand_visual_context (palette, default_aspect_ratio, forbidden_styles). Apply automatically.\n2. Build prompt per recipe above.\n3. Call higgsfield_generate_image. Capture the request_id.\n4. Poll higgsfield_job_status every 5 seconds until status=''completed'' or ''failed''. Stop after 24 polls (2 min).\n5. Return the output URL plus the prompt used (so the user can iterate).\n6. save_memory under ''higgsfield.soul_history'' with date, prompt summary, output URL.\n\nFailure modes:\n- Job fails or times out \u2192 return error verbatim, suggest a tighter prompt or different aspect ratio.\n- Forbidden_styles violated by user request \u2192 flag once, then proceed if user confirms."}'::jsonb, 'builtin', 'public', 2),
('higgsfield-hex-color', 'Higgsfield HEX Color Control', 'Generates SOUL images locked to a specific brand HEX palette. Encodes Higgsfield''s ''What the HEX'' guide for precise color control in AI image generation.', '1.0.0', '{"slug": "higgsfield-hex-color", "name": "Higgsfield HEX Color Control", "version": "1.0.0", "description": "Generates SOUL images locked to a specific brand HEX palette. Encodes Higgsfield''s ''What the HEX'' guide for precise color control in AI image generation.", "triggers": [{"type": "keyword", "match": ["brand color image", "hex palette image", "soul hex", "match brand colors", "color-locked image", "palette image"]}], "tools_required": ["higgsfield_generate_image", "higgsfield_job_status", "save_memory"], "tools_optional": ["search_wisdom_memories", "web_scrape"], "memory_domains": ["higgsfield.brand_visual_context"], "modes_allowed": ["focus", "reactive"], "side_effect": "external_call", "requires_confirmation": false, "instructions": "You generate brand-color-accurate stills with Higgsfield SOUL HEX.\n\nInputs (collect, in order):\n1. Up to 5 HEX codes (e.g. #1A1A1A, #FF6B35). If user pastes a brand site URL instead, web_scrape it and extract dominant HEX codes (look at hero, primary CTA, links).\n2. Subject and setting.\n\nPalette rules (per Higgsfield HEX guide):\n- 1 dominant color (~60% of frame), 1 secondary (~30%), 1-3 accents (~10% combined).\n- Order matters: list dominant FIRST in the prompt.\n- Pair light + dark codes for contrast; flag if all codes have similar luminance.\n- For a single-color brand, derive a palette by adding a neutral (#FFFFFF or #0A0A0A) and one warm/cool accent.\n\nPrompt template:\n''<SUBJECT>, <SETTING>, <LIGHTING>, <LENS/COMPOSITION>, brand palette: #DOMINANT, #SECONDARY, #ACCENT1, #ACCENT2 \u2014 #DOMINANT dominant, <ACCENT> highlights, photographic realism''\n\nFlow:\n1. Save the supplied HEX palette to higgsfield.brand_visual_context.brand_palette_hex via save_memory (overwrite if user supplies new ones).\n2. Build the prompt per template above. Apply default_aspect_ratio from memory if set.\n3. higgsfield_generate_image \u2192 poll higgsfield_job_status to completion.\n4. Return image URL + the exact palette used + a 1-line note on dominance.\n\nFailure modes:\n- Output drifts from palette \u2192 regenerate with the dominant color repeated twice in the prompt.\n- User gives 6+ HEX codes \u2192 keep top 5 and explain why."}'::jsonb, 'builtin', 'public', 2),
('higgsfield-moodboard', 'Higgsfield Moodboard', 'Builds a custom AI art-style reference (moodboard) and generates on-style images from it. Encodes Higgsfield''s official moodboard workflow for SOUL 2.0.', '1.0.0', '{"slug": "higgsfield-moodboard", "name": "Higgsfield Moodboard", "version": "1.0.0", "description": "Builds a custom AI art-style reference (moodboard) and generates on-style images from it. Encodes Higgsfield''s official moodboard workflow for SOUL 2.0.", "triggers": [{"type": "keyword", "match": ["moodboard", "art style", "style reference", "aesthetic", "visual style guide", "build a style"]}], "tools_required": ["higgsfield_generate_image", "higgsfield_job_status", "save_memory"], "tools_optional": ["search_wisdom_memories", "web_scrape"], "memory_domains": ["higgsfield.brand_visual_context", "higgsfield.moodboards"], "modes_allowed": ["focus", "planning"], "side_effect": "external_call", "requires_confirmation": false, "instructions": "You define an aesthetic, persist it as a reusable moodboard, and generate on-style images.\n\nA moodboard = a structured set of 6 attributes that get appended to every prompt:\n- color_palette: 3-5 HEX codes\n- lighting_style: 1 sentence (e.g. ''overcast Nordic daylight, no specular highlights'')\n- texture_grain: 1 phrase (''35mm Portra grain'', ''clean digital'', ''risograph stipple'')\n- composition_rule: 1 phrase (''negative space top-third, subject lower-left'')\n- subject_treatment: 1 phrase (''candid, mid-action, never posed'')\n- mood_adjectives: 2 words (''quiet, defiant'')\n\nFlow:\n1. If the user names an existing moodboard, load it from higgsfield.moodboards via search_wisdom_memories.\n2. Otherwise build one: ask up to 3 short questions to fill missing attributes (use 1-line examples). Optionally web_scrape a reference URL.\n3. Save the complete moodboard via save_memory under higgsfield.moodboards.<board_name>.v1, plus link in higgsfield.brand_visual_context.active_moodboard.\n4. To generate: build the SOUL prompt as SUBJECT + SETTING, then APPEND the 6 moodboard attributes verbatim.\n5. higgsfield_generate_image \u2192 poll \u2192 return URL + moodboard name used.\n\nRules:\n- Never invent attributes the user didn''t approve.\n- Same moodboard across many images = consistent series; that is the point.\n- If the user says ''tweak the moodboard'', show the current 6 attributes, change only what they specify, save a new version (v2)."}'::jsonb, 'builtin', 'public', 2),
('higgsfield-sora2-video', 'Higgsfield Sora 2 Video', 'Writes director-grade Sora 2 prompts for short viral videos. Encodes Higgsfield''s official Sora 2 prompting guide (shot composition, motion & timing, palette, dialogue).', '1.0.0', '{"slug": "higgsfield-sora2-video", "name": "Higgsfield Sora 2 Video", "version": "1.0.0", "description": "Writes director-grade Sora 2 prompts for short viral videos. Encodes Higgsfield''s official Sora 2 prompting guide (shot composition, motion & timing, palette, dialogue).", "triggers": [{"type": "keyword", "match": ["sora 2", "sora2", "viral video", "short video ad", "social video", "tiktok ai video", "ai short"]}], "tools_required": ["higgsfield_generate_video", "higgsfield_job_status"], "tools_optional": ["higgsfield_generate_image", "search_wisdom_memories", "save_memory"], "memory_domains": ["higgsfield.brand_visual_context", "higgsfield.sora2_history"], "modes_allowed": ["focus", "reactive"], "side_effect": "external_call", "requires_confirmation": false, "instructions": "You write Sora 2 prompts the way the Higgsfield Head of Engineering recommends.\n\nCore strengths to leverage:\n- Shot composition: detail framing, depth of field, lighting, palette, action like a storyboard line.\n- Motion & timing: name the camera move (push in, pull out, orbit, whip pan, locked off) AND its duration in seconds.\n- Subject action: one verb, present tense, clearly resolvable in <=10 seconds.\n- Continuity: keep wardrobe, palette, location consistent within a clip.\n\nPrompt template (one paragraph, comma separated):\n''<FRAMING> of <SUBJECT+ATTRIBUTES> in <SETTING>, <LIGHTING>, <PALETTE>. <CAMERA MOVE> over <DURATION>s as <SUBJECT> <ACTION>. <ATMOSPHERE/SOUND CUE>. <ASPECT RATIO>.''\n\nRules:\n- Default duration 5-8s for social, 10s max.\n- One camera move per clip. One primary subject action.\n- No emojis. No ''cinematic 8k masterpiece'' filler \u2014 Sora 2 ignores it and it costs tokens.\n- For dialogue, write it on its own line in quotes after the visual prompt: ''\"<line>\" \u2014 <SUBJECT>, lip-synced.''\n- For ads, end with a 1-second product hold or logo beat.\n\nFlow:\n1. Pull brand_visual_context (palette, character_refs, default_aspect_ratio).\n2. If user gives a still as starting point \u2192 use higgsfield_generate_video with that image_url and a MOTION-only prompt.\n3. If pure text-to-video \u2014 first higgsfield_generate_image to lock the look, then animate with higgsfield_generate_video.\n4. Poll higgsfield_job_status to completion. Return the video URL, the still URL (if intermediate), the exact prompt used, and a 1-line note on what to change for variant 2.\n5. save_memory under higgsfield.sora2_history with date, prompt, output URL.\n\nFailure modes:\n- Subject morphs mid-clip \u2192 reduce action complexity to one verb, pin wardrobe details, regenerate.\n- Motion ignored \u2192 move the camera move to the start of the prompt and shorten the rest."}'::jsonb, 'builtin', 'public', 2),
('higgsfield-seedance', 'Higgsfield Seedance 2.0', 'Writes Seedance 2.0 prompts using Higgsfield''s official guide. Always declares shot structure (number of shots, total duration, aspect ratio) upfront. Supports transformations, orbs, POVs, fights, animation.', '1.0.0', '{"slug": "higgsfield-seedance", "name": "Higgsfield Seedance 2.0", "version": "1.0.0", "description": "Writes Seedance 2.0 prompts using Higgsfield''s official guide. Always declares shot structure (number of shots, total duration, aspect ratio) upfront. Supports transformations, orbs, POVs, fights, animation.", "triggers": [{"type": "keyword", "match": ["seedance", "transformation video", "orb shot", "pov video", "fight scene", "ai animation", "ai cartoon"]}], "tools_required": ["higgsfield_generate_video", "higgsfield_job_status"], "tools_optional": ["higgsfield_generate_image", "search_wisdom_memories", "save_memory"], "memory_domains": ["higgsfield.brand_visual_context", "higgsfield.seedance_history"], "modes_allowed": ["focus", "reactive"], "side_effect": "external_call", "requires_confirmation": false, "instructions": "You write Seedance 2.0 prompts. The single rule that overrides all others (per Higgsfield''s guide): ALWAYS specify shot structure upfront \u2014 number of shots, total duration, aspect ratio \u2014 at the very top of the prompt. Everything else follows.\n\nFormat header (line 1, every time):\n''[<N> shots, <total_seconds>s total, <aspect_ratio>] \u2014 <FORMAT>''\n\nFormats supported (pick one, name it):\n- TRANSFORMATION: subject morphs A \u2192 B over the duration (e.g. ''street clothes \u2192 samurai armor'').\n- ORB: 360-degree orbit around a static subject; 1 shot, 6-8s.\n- POV: first-person; subject''s hands and gaze visible.\n- FIGHT: 2 subjects, choreographed exchange; specify who wins and on which beat.\n- ANIMATION: stylized (anime, claymation, watercolor); name the style.\n- CINEMATIC: multi-shot narrative; each shot one line.\n\nPer-shot block (after header):\n''Shot <n> (<seconds>s): <FRAMING> of <SUBJECT> in <SETTING>, <LIGHTING>, <CAMERA MOVE>, <ACTION>.''\n\nRules:\n- Total of per-shot durations MUST equal header total_seconds.\n- One camera move per shot. One verb of action per shot.\n- For TRANSFORMATION, describe the midpoint visually so the model knows the in-between.\n- For ANIMATION, name the style ONCE in the header, do not repeat per shot.\n- No emojis. Plain-speak.\n\nFlow:\n1. Pull brand_visual_context.\n2. If image-to-video, the user-supplied still is the opening frame of Shot 1.\n3. Build prompt with header + per-shot blocks.\n4. higgsfield_generate_video \u2192 poll higgsfield_job_status. Return URL + the full prompt + which format was used.\n5. save_memory under higgsfield.seedance_history.\n\nFailure modes:\n- Shots blur into each other \u2192 tighten per-shot framing, add hard cut markers between blocks.\n- Transformation skips midpoint \u2192 add an explicit Shot 2 describing the half-state."}'::jsonb, 'builtin', 'public', 2),
('higgsfield-dop-camera', 'Higgsfield DoP Camera Control', 'Image-to-video with cinematic camera motion using Higgsfield DoP / WAN. Encodes the official camera-control vocabulary: push in, pull out, orbit, dolly, crane, whip pan, parallax, rack focus.', '1.0.0', '{"slug": "higgsfield-dop-camera", "name": "Higgsfield DoP Camera Control", "version": "1.0.0", "description": "Image-to-video with cinematic camera motion using Higgsfield DoP / WAN. Encodes the official camera-control vocabulary: push in, pull out, orbit, dolly, crane, whip pan, parallax, rack focus.", "triggers": [{"type": "keyword", "match": ["camera move", "push in", "orbit shot", "dolly", "crane shot", "image to video", "animate this image", "dop video", "wan camera"]}], "tools_required": ["higgsfield_generate_video", "higgsfield_job_status"], "tools_optional": ["search_wisdom_memories", "save_memory"], "memory_domains": ["higgsfield.brand_visual_context", "higgsfield.dop_history"], "modes_allowed": ["focus", "reactive"], "side_effect": "external_call", "requires_confirmation": false, "instructions": "You animate a still into a cinematic clip with Higgsfield DoP. The prompt describes MOTION ONLY \u2014 the still already carries subject and setting.\n\nRequired input: image_url. If missing, ask for it; do NOT generate the still here (route back to higgsfield-soul-image).\n\nCamera-move vocabulary (use the exact terms \u2014 DoP recognizes them):\n- push_in / pull_out \u2014 dolly along the lens axis\n- orbit_left / orbit_right \u2014 circular around subject\n- pan_left / pan_right \u2014 horizontal rotation, fixed pivot\n- tilt_up / tilt_down \u2014 vertical rotation\n- crane_up / crane_down \u2014 vertical translation\n- truck_left / truck_right \u2014 horizontal translation\n- whip_pan \u2014 fast pan with motion blur\n- rack_focus \u2014 depth-of-field shift between two planes\n- parallax \u2014 slow truck while subject stays centered (great for product hero)\n- locked_off \u2014 no camera move, only subject motion\n\nPrompt template:\n''<CAMERA MOVE> over <DURATION>s. Subject: <ACTION VERB> (e.g. \"breath rises\", \"hair drifts\", \"hand reaches\"). Atmosphere: <ONE SENSORY DETAIL>.''\n\nRules:\n- One camera move per clip. Combining two reads as drift.\n- Duration 4-8s default; longer needs a second clip stitched.\n- Subject action stays subtle when camera is moving fast (whip_pan, push_in).\n- For product shots, prefer parallax or orbit_right at 6s.\n- No emojis.\n\nFlow:\n1. Confirm image_url is reachable.\n2. Build motion-only prompt.\n3. higgsfield_generate_video with image_url + prompt + duration.\n4. Poll higgsfield_job_status. Return video URL + the camera move chosen + 1-line suggestion for a B-roll variant.\n5. save_memory under higgsfield.dop_history.\n\nFailure modes:\n- Subject melts during motion \u2192 reduce camera speed, shorten duration, or switch to locked_off with subject action.\n- Motion too subtle \u2192 name it twice in the prompt or shorten duration."}'::jsonb, 'builtin', 'public', 2),
('higgsfield-popcorn-consistency', 'Higgsfield Popcorn Consistency', 'Maintains the same character, lighting, and tone across multiple images or scenes using Higgsfield Popcorn. Solves the AI ''consistency gap'' for series, storyboards, and ad campaigns.', '1.0.0', '{"slug": "higgsfield-popcorn-consistency", "name": "Higgsfield Popcorn Consistency", "version": "1.0.0", "description": "Maintains the same character, lighting, and tone across multiple images or scenes using Higgsfield Popcorn. Solves the AI ''consistency gap'' for series, storyboards, and ad campaigns.", "triggers": [{"type": "keyword", "match": ["character consistency", "same character", "same person across", "series of images", "storyboard with same", "popcorn", "consistent look"]}], "tools_required": ["higgsfield_generate_image", "higgsfield_job_status", "save_memory"], "tools_optional": ["search_wisdom_memories"], "memory_domains": ["higgsfield.brand_visual_context", "higgsfield.character_refs"], "modes_allowed": ["focus", "planning"], "side_effect": "external_call", "requires_confirmation": false, "instructions": "You enforce visual consistency across a sequence using Higgsfield Popcorn principles.\n\nThe consistency gap: faces drift, lighting shifts, palette fades between generations. The fix is a stable CHARACTER CARD that gets appended to every prompt in the series.\n\nCharacter Card schema (save once, reuse forever):\n- char_name: short slug (e.g. ''maya_v1'')\n- physical: age range, build, hair (color + style), eyes, skin tone, distinguishing marks (1-2)\n- wardrobe_signature: 1-2 fixed garments that appear in every shot\n- lighting_signature: 1 phrase (e.g. ''warm key from camera left, cool fill'')\n- palette_lock: 3-5 HEX from brand_visual_context\n- mood_signature: 2 adjectives\n- reference_image_url: optional anchor still\n\nFlow:\n1. If user names an existing character (e.g. ''use maya_v1''), load it from higgsfield.character_refs.\n2. Otherwise build one: ask for the 5 physical fields + wardrobe in one short message, then save_memory under higgsfield.character_refs.<char_name>.v1.\n3. For every image in the series, prompt = SCENE-SPECIFIC PROMPT + verbatim character card serialized as comma-separated attributes + palette HEX codes.\n4. Generate sequentially (NOT in parallel) so each output can be visually checked against the previous one before continuing.\n5. After generating image N, briefly note: ''Consistency check: face match high/medium/low, palette match high/medium/low''. If ''low'' twice in a row, stop and ask the user whether to re-anchor or revise the card.\n6. Return all image URLs in order + the character_name used.\n\nRules:\n- Never describe the character differently between shots \u2014 copy the card verbatim.\n- New scene = new SETTING + LIGHTING context only; character block is immutable.\n- For video extension, hand off to higgsfield-dop-camera with the consistent stills as anchors.\n\nFailure modes:\n- Face drift on shot 3+ \u2192 regenerate that shot with reference_image_url passed back into the prompt and the card repeated twice."}'::jsonb, 'builtin', 'public', 2),
('higgsfield-multi-scene', 'Higgsfield Multi-Scene Builder', 'Builds cohesive multi-scene videos and instant-ad packages by storyboarding, generating per-scene assets, and stitching them. Encodes Higgsfield''s multi-scene + instant-ads guides.', '1.0.0', '{"slug": "higgsfield-multi-scene", "name": "Higgsfield Multi-Scene Builder", "version": "1.0.0", "description": "Builds cohesive multi-scene videos and instant-ad packages by storyboarding, generating per-scene assets, and stitching them. Encodes Higgsfield''s multi-scene + instant-ads guides.", "triggers": [{"type": "keyword", "match": ["multi scene", "multi-scene", "instant ad", "full ad package", "ad package", "video ad", "30 second ad", "story driven video", "narrative video"]}], "tools_required": ["load_skill", "higgsfield_generate_image", "higgsfield_generate_video", "higgsfield_job_status", "save_memory"], "tools_optional": ["search_wisdom_memories"], "memory_domains": ["higgsfield.brand_visual_context", "higgsfield.character_refs", "higgsfield.multiscene_projects"], "modes_allowed": ["focus", "planning"], "side_effect": "external_call", "requires_confirmation": true, "instructions": "You produce a cohesive multi-scene piece: storyboard \u2192 per-scene stills \u2192 per-scene motion \u2192 assembly notes.\n\nStep 1 \u2014 Brief intake (one short message, get):\n- objective (ad, social cut, brand film, product launch)\n- duration_total (15s, 30s, 60s)\n- platform (TikTok, Reels, YouTube short, OOH)\n- protagonist (link to a character_card if exists)\n- product or message\n\nStep 2 \u2014 Storyboard:\n- Break duration_total into 3-6 beats, each 3-8s.\n- For each beat write: BEAT_NAME, intent (1 line), shot description (framing+subject+action+lighting), motion (camera move + duration), audio cue (1 line).\n- Show storyboard table, ASK USER TO CONFIRM before any generation. (requires_confirmation=true)\n\nStep 3 \u2014 Generate stills (sequential):\n- For each beat, hand off to higgsfield-popcorn-consistency to generate the opening still using the locked character_card + brand palette.\n\nStep 4 \u2014 Animate each still:\n- For each still, hand off to higgsfield-dop-camera with the beat''s motion description and duration.\n\nStep 5 \u2014 Assembly notes:\n- Output a final block listing: ordered video URLs, per-clip duration, recommended cut style between clips (hard cut, match cut, dissolve), one suggested SFX per clip, and the on-screen text for any beat that needs it.\n- Save the whole project under higgsfield.multiscene_projects.<project_slug> with brief, storyboard, asset URLs.\n\nRules:\n- Never run scenes in parallel; consistency requires sequential generation with checks.\n- If a beat fails 2x, pause and ask the user to revise that beat''s prompt rather than burning more credits.\n- For ''instant ad'' requests, default to 6 beats over 30s, 9:16, ending on a 2s product hold + on-screen CTA.\n- No emojis. Plain-speak."}'::jsonb, 'builtin', 'public', 2)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  version = EXCLUDED.version,
  manifest = EXCLUDED.manifest,
  source = EXCLUDED.source,
  visibility = EXCLUDED.visibility,
  trust_tier = EXCLUDED.trust_tier,
  updated_at = now();
